-- Databricks Free Edition: bronze for 2013, same pattern as 05_phase2_full_load.sql
-- (2015). Part of the 5-year extension (2026-09-29) - each year gets its own bronze
-- table because each year's CSV has a different column set (336 columns for 2013;
-- see docs/scope_and_gaps.md for the full 454/359/336/279/330 breakdown). Silver unions
-- all 5 bronze tables together (see 03b_silver_multiyear.sql).

DROP TABLE IF EXISTS workspace.bronze.brfss_2013;

CREATE TABLE workspace.bronze.brfss_2013 AS
